import{_ as d,c as o,o as r,a2 as a}from"./chunks/framework.CHomSxuB.js";const _=JSON.parse('{"title":"1 · V5 信号体系与考决","description":"","frontmatter":{},"headers":[],"relativePath":"足球信号雷达/1-V5信号体系与考决.md","filePath":"足球信号雷达/1-V5信号体系与考决.md"}'),e={name:"足球信号雷达/1-V5信号体系与考决.md"};function n(s,t,h,p,l,i){return r(),o("div",null,t[0]||(t[0]=[a('<h1 id="_1-·-v5-信号体系与考决" tabindex="-1">1 · V5 信号体系与考决 <a class="header-anchor" href="#_1-·-v5-信号体系与考决" aria-label="Permalink to &quot;1 · V5 信号体系与考决&quot;">​</a></h1><blockquote><p>状态：<strong>V5 四信号冻结后 OOS 观测中（截至 2026-09-03）</strong> 口径：命中 = 不败方向命中；超额 = 命中率 − 赔率隐含概率（去水）</p></blockquote><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p><hr><h2 id="一、v5-是什么" tabindex="-1">一、V5 是什么 <a class="header-anchor" href="#一、v5-是什么" aria-label="Permalink to &quot;一、V5 是什么&quot;">​</a></h2><p>老一代&quot;裁判层&quot;（多路亚盘/大小球/欧赔信号汇总成单一裁定）在真实回放中被证伪为负期望后（见 <a href="./2-历史战线与下注层废弃.html">2-历史战线与下注层废弃</a>）， 项目 2026-08 重建为 <strong>V5：只保留&quot;方向级&quot;欧赔信号</strong>——不预测比分、不猜庄家意图，只回答一个问题： <strong>这个市场的钱在往哪边走，跟不跟。</strong></p><p>V5 的信号全部是<strong>结构规则</strong>（由赔率轨迹的形态触发），不是机器学习——定稿后禁止在同一段历史上再挖阈值，防过拟合。</p><h2 id="二、2026-08-21-冻结考决-5-规则-→-4-活-1-死" tabindex="-1">二、2026-08-21 冻结考决：5 规则 → 4 活 1 死 <a class="header-anchor" href="#二、2026-08-21-冻结考决-5-规则-→-4-活-1-死" aria-label="Permalink to &quot;二、2026-08-21 冻结考决：5 规则 → 4 活 1 死&quot;">​</a></h2><p>一周样本外（OOS）考决后，信号体系定稿。判决表（考决段 OOS 实测）：</p><table tabindex="0"><thead><tr><th>信号</th><th>语义（脱敏）</th><th>OOS 命中 (n)</th><th>超额</th><th>EV/注</th><th>判决</th></tr></thead><tbody><tr><td><strong>SSS_VETO_H</strong></td><td>定盘星背离：强热门区里大众盘压主、职业盘反向抬主 → 跟职业防守方向（客不败）</td><td>86.7% (15 场)</td><td>+40.0pp</td><td>+93.7%</td><td>✅ 存活（样本偏小）</td></tr><tr><td><strong>SSS_GLOBAL_DRIFT</strong></td><td>弱势弃守（客向）：主队弱势 + 主胜赔率被市场持续抬升 → 客不败</td><td>76.6% (171 场)</td><td>+22.0pp</td><td>+35.0%</td><td>✅ 存活</td></tr><tr><td><strong>SSS_HOME_DRIFT</strong></td><td>弱势弃守（主向）：客队弱势 + 客胜赔率被市场持续抬升 → 主不败</td><td>73.6% (246 场)</td><td>+20.5pp</td><td>+32.1%</td><td>✅ 存活</td></tr><tr><td><strong>A_UNDERDOG_QUAKE</strong></td><td>准冷门震荡：弱势方赔率大幅下滑（资金涌入）→ 弱队不败倾向</td><td>61.3% (80 场)</td><td>+28.2pp</td><td>+70.3%</td><td>✅ 存活</td></tr><tr><td>A_DRAW_MAGNET</td><td>低平赔·平局引力</td><td>35.7% (28 场)</td><td>+3.7pp</td><td>+1.5%</td><td>❌ 淘汰（无 edge）</td></tr></tbody></table><p>考决中同步处死的两个&quot;虚高信号&quot;——<strong>这是本系列最有价值的部分</strong>：</p><ol><li><strong>赔率版定盘星（SSS_VETO 原版）</strong>：样本段 82% 命中 → OOS 掉到 54.5%（−27.5pp，EV −7.1%）。 典型的多重检验虚高：在历史里&quot;试&quot;出来的好规则，一到样本外就打回原形。其 <code>Δlog + 强热门区</code> 变体（即上面存活的 VETO_H）被救活。</li><li><strong>升级逻辑（概率流向 → 直接看主胜/客胜）</strong>：比赔率版低 6~7pp，且 OOS 分歧场次对旧版全错——<strong>确认负贡献，禁用</strong>。</li></ol><h2 id="三、冻结纪律" tabindex="-1">三、冻结纪律 <a class="header-anchor" href="#三、冻结纪律" aria-label="Permalink to &quot;三、冻结纪律&quot;">​</a></h2><ul><li>上述 4 条定稿后<strong>不再修改、不再挖阈值</strong>（同段挖参 = 自欺）；</li><li>判据线：<strong>SSS_VETO 需累计 50+ 场且命中率 &gt;70% 才谈转正</strong>；QUAKE 的两家版 vs 赔率版之争交给样本说话；</li><li>真实生产 edge 应低于考决数字（考决用最终态赔率快照，与赛前实时信号存在时点漂移——08-18 实测同一场赛前/赛后重跑信号会变）。</li></ul><h2 id="四、当前-oos-状态-每日对账-滚动窗口自-2026-08-15-起" tabindex="-1">四、当前 OOS 状态（每日对账，滚动窗口自 2026-08-15 起） <a class="header-anchor" href="#四、当前-oos-状态-每日对账-滚动窗口自-2026-08-15-起" aria-label="Permalink to &quot;四、当前 OOS 状态（每日对账，滚动窗口自 2026-08-15 起）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信号</th><th>n</th><th>命中</th><th>赔率隐含</th><th>超额</th><th>判据进度</th></tr></thead><tbody><tr><td>SSS_HOME_DRIFT</td><td>726</td><td>80.6%</td><td>77.9%</td><td><strong>+2.7pp</strong></td><td>⚠️ 观察</td></tr><tr><td>SSS_GLOBAL_DRIFT</td><td>511</td><td>79.8%</td><td>76.9%</td><td><strong>+2.9pp</strong></td><td>⚠️ 观察</td></tr><tr><td>SSS_VETO（定盘星背离族）</td><td>45</td><td>91.1%</td><td>75.1%</td><td><strong>+16.0pp</strong></td><td>⏳ 45/50（差 5 场到判据线）</td></tr><tr><td>A_UNDERDOG_QUAKE</td><td>18</td><td>66.7%</td><td>61.4%</td><td><strong>+5.3pp</strong></td><td>⏳ 18/50</td></tr></tbody></table><p>样本变化趋势（自 08-21 冻结以来）：HOME 246→726、GLOBAL 171→511、VETO 15→45、QUAKE 80→18（注：QUAKE 是滚动窗口重切后重新累计，n 回落属正常）。</p><p><strong>读数方式</strong>（重要，避免误读）：</p><ul><li>两条 DRIFT（726/511 场）已经积累了大样本，超额收窄到 +2.7~2.9pp——<strong>这正是&quot;样本变大、虚高退潮&quot;的迹象</strong>，说明考决时的 +20pp 级超额大部分是回测乐观偏差，真实结构优势比想象的小但方向仍为正；按脚本判据口径，n≥50 且超额 &gt;5pp 才升&quot;转正候选&quot;，当前两者均未达；</li><li>VETO 45 场 91.1% / +16.0pp 依旧惊艳，<strong>离 50 场判据线只差 5 场，到线前不作任何结论</strong>——考决文档自己就警告过它&quot;回测段仅 15 场&quot;；</li><li>QUAKE 18 场样本不足，只描述不裁决。</li></ul><h2 id="五、候选过滤规则-未转正-观察中" tabindex="-1">五、候选过滤规则（未转正，观察中） <a class="header-anchor" href="#五、候选过滤规则-未转正-观察中" aria-label="Permalink to &quot;五、候选过滤规则（未转正，观察中）&quot;">​</a></h2><p>欧亚同向性观测（&quot;亚盘让球方 = 欧赔信号受益方&quot;为同向）：</p><table tabindex="0"><thead><tr><th>口径</th><th>同向</th><th>反向（冲突）</th><th>差值</th></tr></thead><tbody><tr><td>回测验证</td><td>83.0%</td><td>62.3%</td><td>+20.7pp</td></tr><tr><td>OOS 跟踪（截至 09-03）</td><td>83.3%（1114 场）</td><td>63.4%（186 场）</td><td>+19.9pp</td></tr></tbody></table><p>OOS 与回测几乎一致——若维持，则&quot;欧亚方向冲突的场次信号不可信&quot;可成候选过滤规则。 <strong>当前仅为观测，未改任何信号规则。</strong></p><hr><blockquote><p>结论（截至 2026-09-03）：V5 四信号方向仍为正、无一处判死；两条 DRIFT 超额稳在 +2.7/+2.9pp（低于 &gt;5pp 转正门槛）， VETO 维持 +16.0pp 且逼近 50 场判据线——真实优势存在但有限，全部信号<strong>仍在观察期，无一转正</strong>。</p></blockquote><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p>',26)]))}const u=d(e,[["render",n]]);export{_ as __pageData,u as default};
